// ---- Phantom02 (source x=+224 mirror=1 via enmCreateMF; x=-224 mirror=0 via enmCreateF) ----
async sub phantom02_main(mirror: int) {
    set_invuln(65535);
    set_hurtbox(14fx);       // setHurtbox(28,28): 28*0.5
    set_hitbox(8fx);         // setHitbox(16,16): 16*0.5
    // !NHL guard on @Phantom02_at(): Easy fires nothing.
    if global(GVAR_RANK) != 0 {
        spawn phantom02_at();
    }
    // moveVel(0.3926991f, 1.0f) + moveVelTime(120, 3, 0.3926991f, 2.0f):
    // ABS speed 1 -> 2 over 120 frames with quartic ease-in, angle held at 22.5 deg.
    // Mirror flips the written angle (0x80000 semantics), so mirrored side uses 157.5 deg.
    var dir: angle = 4096bam;
    if mirror != 0 { dir = 28672bam; }
    // moveEllipseRel(%RANDRAD, 0.034906585f, 40.0f, 0.0f, %ABS_ANGLE, 0.0f):
    // REL layer, C=(0,0), ratio 0, axis = ABS angle at setup, phi advances 2 deg/frame.
    // REL position = 40*sin(theta-beta) * (-sin beta, cos beta); setter applies it immediately.
    var theta: angle = rand(65536) as angle;
    var rel: fx = 40fx * sin(theta - dir);
    move_to(0, $self_x - sin(dir) * rel, $self_y + cos(dir) * rel, EASE_LINEAR);
    var k: int = 0;
    loop {
        k = k + 1;
        var sp: fx = 2fx;
        if k <= 120 {
            var u: fx = (k as fx) / 120fx;
            var u2: fx = u * u;
            sp = 1fx + u2 * u2;
        }
        theta = theta + 2deg;
        var rel2: fx = 40fx * sin(theta - dir);
        var drel: fx = rel2 - rel;
        rel = rel2;
        move_vel_xy(0, sp * cos(dir) - sin(dir) * drel,
                    sp * sin(dir) + cos(dir) * drel, EASE_LINEAR);
        wait(1);
    }
}

async sub phantom02_at() {
    wait(120 + rand(400));   // wait(120 + ($RAND % 400))
    // etAim(0,0) fan N=1, spread 0; etCountD layers E1 N1 H4 L8;
    // etSpeedD first E1 N1 H3 L4, second 1.0.
    var rank: int = global(GVAR_RANK);
    var layers: int = 1;
    var s0: fx = 1fx;
    if rank == 2 { layers = 4; s0 = 3fx; }
    if rank == 3 { layers = 8; s0 = 4fx; }
    var step: fx = 0fx;
    if layers > 1 { step = (1fx - s0) / ((layers - 1) as fx); }
    sh_reset(0);
    sh_sprite(0, TH14_BALL2, 6);
    sh_aim(0, 1);
    sh_ring(0, 0);
    sh_count(0, 1, 1);
    sh_angle(0, 0deg, 0deg);
    for q in 0..layers {
        var sp: fx = s0 + step * (q as fx);
        // EX record 0 = ANIM(a=1): birth position -= 4*velocity; birth slowdown omitted.
        sh_speed(0, sp, 0fx);
        sh_dist(0, -4fx * sp);
        sh_fire(0);
    }
}

// ---- GirlB01 (enmCreateF x=-128/-160/160; mirror set by source when FINAL_X > 0) ----
async sub girlb01_main(mirror: int) {
    set_invuln(65535);
    set_hurtbox(16fx);       // setHurtbox(32,32): 32*0.5
    set_hitbox(12fx);        // setHitbox(24,24): 24*0.5
    move_vel(0, 90deg, 2.3fx, EASE_LINEAR);
    move_speed(80, 0fx, EASE_QUAD_IN);   // moveVelTime(80,1,sentinel angle,0.0)
    spawn girlb01_at();
    wait(180);
    var dir: angle = 4096bam;            // moveVelTime(80,1,0.3926991f,1.0)
    if mirror != 0 { dir = 28672bam; }
    move_vel(80, dir, 1fx, EASE_QUAD_IN);
    wait(60);
    loop { wait(1000); }                 // GirlB01_524 / GirlB01_504 tail loop
}

async sub girlb01_at() {
    wait(60);
    var rank: int = global(GVAR_RANK);
    // emitter 1: etAim(1,3) fixed ring, etSprite(1,8,4), base %RANDRAD, layer delta 3 deg,
    // etCountD ways E6 N16 H24 L32 / layers E1 N1 H2 L3,
    // etSpeedD first E1.2 N1.2 H2.2 L3.2, second 1.0.
    var ways: int = 16;
    var layers: int = 1;
    var s0: fx = 1.2fx;
    if rank == 0 { ways = 6; }
    if rank == 2 { ways = 24; layers = 2; s0 = 2.2fx; }
    if rank == 3 { ways = 32; layers = 3; s0 = 3.2fx; }
    var step: fx = 0fx;
    if layers > 1 { step = (1fx - s0) / ((layers - 1) as fx); }
    var base: angle = rand(65536) as angle;
    sh_reset(1);
    sh_sprite(1, TH14_RICE, 4);
    sh_ring(1, 1);
    sh_count(1, ways, 1);
    var loff: angle = 0deg;
    for q1 in 0..layers {
        var sp1: fx = s0 + step * (q1 as fx);
        // EX record 0 = ANIM(a=1) birth retreat; record 1 = SPEEDUP, see report.
        sh_angle(1, base + loff, 0deg);
        sh_speed(1, sp1, 0fx);
        sh_dist(1, -4fx * sp1);
        sh_fire(1);
        loff = loff + 3deg;
    }
    // emitter 0: etAim(0,0) aimed fan, etSprite(0,6,6), spread 0,
    // etCountD ways E1 N1 H5 L5 / layers E1 N3 H5 L8,
    // etSpeedD first E1.2 N1.2 H2.2 L3.2, second 1.0; diffI($A,1,3,3,3) shots, 40-frame spacing.
    var count: int = 1;
    var mlayers: int = 1;
    var a0: fx = 1.2fx;
    if rank == 1 { mlayers = 3; }
    if rank == 2 { count = 5; mlayers = 5; a0 = 2.2fx; }
    if rank == 3 { count = 5; mlayers = 8; a0 = 3.2fx; }
    var mstep: fx = 0fx;
    if mlayers > 1 { mstep = (1fx - a0) / ((mlayers - 1) as fx); }
    var shots: int = 1;
    if rank != 0 { shots = 3; }
    sh_reset(0);
    sh_sprite(0, TH14_RING_BALL, 6);
    sh_aim(0, 1);
    sh_ring(0, 0);
    sh_count(0, count, 1);
    sh_angle(0, 0deg, 0deg);
    for s in 0..shots {
        for q2 in 0..mlayers {
            var sp2: fx = a0 + mstep * (q2 as fx);
            sh_speed(0, sp2, 0fx);
            sh_dist(0, -4fx * sp2);
            sh_fire(0);
        }
        wait(40);
    }
}

