// ---- MainSub04: 33 MF Phantom02 then 13 F Phantom02, 30 frames apart ----
async sub pattern() {
    wait(OPENING_BUFFER);
    spawn mainsub04b();
    var n: int = 33;
    while n > 0 {
        // enmCreateMF(..., 224.0f, -32 + RANDF*64, 100, 1000, 1)
        var u1: fx = ((rand(65536) - 32768) as fx / 16384fx) * 0.25fx + 0.5fx;
        _ = spawn_enemy(224fx, -32fx + u1 * 64fx,
                        100, 0, 1000, 0, phantom02_main(1));
        n = n - 1;
        wait(30);
    }
    var m: int = 13;
    while m > 0 {
        // enmCreateF(..., -224.0f, (-32 + RANDF) + 64, 100, 1000, 1): source expression verbatim.
        var u2: fx = ((rand(65536) - 32768) as fx / 16384fx) * 0.25fx + 0.5fx;
        _ = spawn_enemy(-224fx, 32fx + u2,
                        100, 0, 1000, 0, phantom02_main(0));
        m = m - 1;
        wait(30);
    }
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
